import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Injectable, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session, isDate } from './session';

export interface Rate {
  grade: string;
  /** The first day the rate applies (YYYY-MM-DD); null when it applies from the beginning of time. */
  from: string | null;
  /** A percent with two decimals, as the server stores it. */
  rate: string;
}

/** What due shows for a grade with no rate. */
export const NO_RATE = 'n/a';

// The active sheet's rates for each grade, re-read from the server each time the sheet is loaded.
// A grade may have several, each from a date; on a date the one in force is the one whose from-date
// is the latest on or before it, a rate with no from-date applying from the beginning of time.
// Due is worked out in whole cents and hundredths of a percent, with BigInt, so it is exact.
@Injectable({ providedIn: 'root' })
export class Rates {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  /** By grade, then from-date, the one with none first. */
  readonly rates = signal<Rate[]>([]);
  private loads = 0;

  /** The grade's rate in force on a date (YYYY-MM-DD), or undefined when none applies. */
  inForce(grade: string, date: string): Rate | undefined {
    let found: Rate | undefined;
    for (const r of this.rates()) {
      if (r.grade === grade && (r.from === null || r.from <= date)) found = r;
    }
    return found;
  }

  /** A grade's rate in force on the sheet's today, with two decimals, or n/a when it has none. */
  current(grade: string): string {
    const today = this.session.today();
    return (today ? this.inForce(grade, today)?.rate : undefined) ?? NO_RATE;
  }

  /** An amount in cents times the grade's rate in force on a date, divided by 100, rounded half to
   *  even to cents, and at least the sheet's floor; null when no rate of the grade applies then. */
  dueCents(amountCents: bigint, grade: string, date: string): bigint | null {
    const rate = this.inForce(grade, date);
    if (rate === undefined) return null;
    const due = halfEven(amountCents * hundredths(rate.rate), 10000n);
    const floor = hundredths(this.session.floor());
    return due < floor ? floor : due;
  }

  /** An amount written with two decimals times the grade's rate on a date, as `dueCents`, shown
   *  with two decimals or n/a. */
  due(amount: string, grade: string, date: string): string {
    const d = this.dueCents(hundredths(amount), grade, date);
    return d === null ? NO_RATE : money(d);
  }

  /** Re-read the active sheet's rates from the server; an error message when that failed. */
  async load(): Promise<string | null> {
    const user = this.session.user();
    const sid = this.session.sheetId();
    const load = ++this.loads;
    this.rates.set([]);
    if (!user || !sid) return null;
    try {
      const rates = await firstValueFrom(this.http.get<Rate[]>(this.url(sid), { headers: { 'X-User': user } }));
      if (load === this.loads) this.rates.set([...rates].sort(byGradeAndFrom));
      return null;
    } catch (e) {
      return failed('load', e).replace(' rate', ' rates');
    }
  }

  /** Set a grade's rate from a date (blank: from the beginning of time), replacing the one it had
   *  from that date; an error message when refused. */
  async set(grade: string, pct: string, from: string): Promise<string | null> {
    if (!this.session.user() || !this.session.sheetId()) return 'Load a sheet first.';
    if (!/^\d+(\.\d{1,2})?$/.test(pct.trim())) return 'Enter a rate of 0.00 or more, with up to two decimals.';
    if (from.trim() && !isDate(from.trim())) return 'Enter a from-date as YYYY-MM-DD, or leave it blank.';
    const sid = this.session.sheetId()!;
    try {
      const rate = await firstValueFrom(
        this.http.put<Rate>(`${this.url(sid)}/${encodeURIComponent(grade)}`, { rate: pct.trim(), from: from.trim() || null }, {
          headers: { 'X-User': this.session.user()! },
        }),
      );
      if (this.session.sheetId() === sid) {
        this.rates.update((rs) =>
          [...rs.filter((r) => r.grade !== rate.grade || r.from !== rate.from), rate].sort(byGradeAndFrom),
        );
      }
      return null;
    } catch (e) {
      return failed('set', e);
    }
  }

  private url(sid: string): string {
    return `/api/sheets/${encodeURIComponent(sid)}/rates`;
  }
}

/** By grade, then from-date, the one with none first. */
function byGradeAndFrom(a: Rate, b: Rate): number {
  return a.grade.localeCompare(b.grade) || (a.from ?? '').localeCompare(b.from ?? '');
}

/** A non-negative number divided by another, rounded half to even. */
export function halfEven(n: bigint, d: bigint): bigint {
  const q = n / d;
  const twice = (n % d) * 2n;
  return twice > d || (twice === d && q % 2n === 1n) ? q + 1n : q;
}

/** A number written with up to two decimals, in hundredths. */
export function hundredths(s: string): bigint {
  const [whole, frac = ''] = s.split('.');
  return BigInt(whole) * 100n + BigInt((frac + '00').slice(0, 2));
}

/** Hundredths written with two decimals. */
export function money(h: bigint): string {
  return `${h / 100n}.${String(h % 100n).padStart(2, '0')}`;
}

function failed(what: string, e: unknown): string {
  if (e instanceof HttpErrorResponse && e.status === 400) return 'Enter a rate of 0.00 or more, with up to two decimals.';
  return e instanceof HttpErrorResponse ? `Could not ${what} rate (${e.status}).` : `Could not ${what} rate.`;
}
  protected checked(e: Event): boolean {
    return (e.target as HTMLInputElement).checked;
  }

  protected value(e: Event): string {
    return (e.target as HTMLInputElement | HTMLSelectElement).value;
  }

  /** The sum of the figures of a person's claims that count live (not OPEN while they are on hold): a settled claim's frozen due, else the
   *  figure their last statement bound it to, else its live due at the rate in force on its date (a
   *  claim with no figure adds nothing). Null when the grade in force on the sheet's today has no rate
   *  there and no claim has a figure. */
  private dueCents(p: Person): bigint | null {
    let sum = 0n;
    let keptFigure = false;
    for (const c of this.claims.live().filter((c) => c.personId === p.id)) {
      if (c.settledDue !== null || (c.stated && c.statedDue !== null)) keptFigure = true;
      // a claim priced at the grade in force on its date keeps a figure too
      else if (!c.stated && this.rates.inForce(gradeOn(p.grades, c.date), c.date) !== undefined) keptFigure = true;
      sum += this.figureCents(c, p);
    }
    const today = this.session.today();
    const rated = today ? this.rates.inForce(gradeOn(p.grades, today), today) !== undefined : false;
    return rated || keptFigure ? sum : null;
  }

  /** A claim's figure: its settled due, else the figure its person's last statement bound it to,
   *  else its live due at the rate in force on its date, an overdue claim's late charge on top;
   *  nothing when it has no figure. */
  private figureCents(c: Claim, p: Person): bigint {
    if (c.settledDue !== null) return hundredths(c.settledDue);
    const f = c.stated
      ? (c.statedDue === null ? 0n : hundredths(c.statedDue))
      : (this.rates.dueCents(hundredths(c.amount), gradeOn(p.grades, c.date), c.date) ?? 0n);
    return f + this.claims.lateCents(c, f);
  }

  /** The grade in force on the sheet's today, the one the list shows. */
  protected gradeToday(p: Person): string {
    const today = this.session.today();
    return today ? gradeOn(p.grades, today) : p.grade;
  }

  /** A person's claims that count live and are overdue. */
  protected overdue(p: Person): Claim[] {
    return this.claims.live().filter((c) => c.personId === p.id && this.claims.overdue(c));
  }

  /** The due of a person's overdue claims that count, added up. */
  private overdueCents(p: Person): bigint {
    return this.overdue(p).reduce((sum, c) => sum + this.figureCents(c, p), 0n);
  }

  protected overdueDue(p: Person): string {
    return money(this.overdueCents(p));
  }

  /** The people a person may choose among as a patron: everyone else on the sheet. */
  protected others(p: Person): Person[] {
    return this.people.people().filter((o) => o.id !== p.id);
  }
  protected readonly acting = signal<number | null>(null);
  protected readonly actionError = signal<{ id: number; message: string } | null>(null);

  /** Each period's due-total, by period id: the figures of the claims that count live whose date falls
   *  in it — a settled claim's frozen due, else as its person's last statement bound it, else its
   *  live due, an overdue claim's late charge on top (a claim with no figure adds nothing). */
  protected readonly dueTotals = computed(() => {
    const grades = new Map(this.people.people().map((p) => [p.id, p.grades]));
    const sums = new Map<number, bigint>();
    for (const c of this.claims.live()) {
      const period = this.periods.of(c.date);
      if (!period) continue;
      let due: bigint | null;
      if (c.settledDue !== null) due = hundredths(c.settledDue);
      else if (c.stated) due = c.statedDue === null ? null : hundredths(c.statedDue);
      else {
        const grade = grades.get(c.personId);
        due = grade === undefined ? null : this.rates.dueCents(hundredths(c.amount), gradeOn(grade, c.date), c.date);
      }
      if (due !== null && c.settledDue === null) due += this.claims.lateCents(c, due);
      sums.set(period.id, (sums.get(period.id) ?? 0n) + (due ?? 0n));
    }
    return new Map([...sums].map(([id, sum]) => [id, money(sum)]));
  });

  protected close(p: Period): Promise<void> {
-- A person's grade is dated: each grade they are given applies from a date, the first from the
-- beginning of time (no from-date). On a date the grade in force is the one whose from-date is the
-- latest on or before it. A person has at most one grade per from-date (and one with none).
CREATE TABLE person_grade (
    id        BIGINT     GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    person_id BIGINT     NOT NULL REFERENCES person (id),
    grade     VARCHAR(1) NOT NULL CHECK (grade IN ('A', 'B', 'C')),
    from_date DATE,
    from_key  DATE GENERATED ALWAYS AS (COALESCE(from_date, DATE '0001-01-01'))
);
CREATE UNIQUE INDEX person_grade_from ON person_grade (person_id, from_key);
INSERT INTO person_grade (person_id, grade, from_date) SELECT id, grade, NULL FROM person;
ALTER TABLE person DROP COLUMN grade;
-- A settled claim's due, fixed when it was settled: its amount times its person's grade's rate at
-- that moment, divided by 100, rounded half up to cents. None while DRAFT or OPEN, and none when
-- the grade had no rate then (such a claim's due stays live).
ALTER TABLE claim ADD COLUMN settled_due DECIMAL(15, 2);

